<?php $kind=$kind??'articles';$rows=$rows??[];$base=admin_url('cms/'.$kind); ?>
<div class="admin-panel-heading"><div><span class="admin-eyebrow">CONTENT MANAGEMENT</span><h2><?= e(ucfirst($kind)) ?></h2></div><div class="admin-detail-actions"><a class="admin-button" href="<?= e(admin_url('cms/categories')) ?>">Categories</a><?php if(in_array('cms.manage',$permissions??[],true)): ?><a class="admin-button admin-button-primary" href="<?= e(admin_url('cms/'.$kind.'/create')) ?>">Create <?= e($kind==='articles'?'Article':($kind==='pages'?'Page':'FAQ')) ?></a><?php endif; ?></div></div>
<form class="admin-panel admin-filter-bar" method="get"><label>Status <select name="status"><option value="">All</option><?php foreach(['draft','published','archived'] as $status): ?><option value="<?= e($status) ?>" <?= ($_GET['status']??'')===$status?'selected':'' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></label><button class="admin-button" type="submit">Filter</button></form>
<section class="admin-panel admin-list-panel"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Title</th><?php if(in_array($kind,['articles','faqs'],true)): ?><th>Category</th><?php endif; ?><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php if(!$rows): ?><tr><td class="admin-empty-cell" colspan="5">No <?= e($kind) ?> found.</td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['title']??$row['question']??'') ?></strong><small class="admin-cell-subtitle"><?= e($row['slug']??$row['category']??'') ?></small></td><?php if(in_array($kind,['articles','faqs'],true)): ?><td><?= e($row['category_name']??$row['category']??'') ?></td><?php endif; ?><td><span class="admin-state-pill <?= $row['status']==='published'?'is-good':'is-muted' ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><?= e($row['updated_at']) ?></td><td><a class="admin-button" href="<?= e(admin_url('cms/'.$kind.'/'.(int)$row['id'].'/edit')) ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></section>
